{
    "$schema": "https://docs.renovatebot.com/renovate-schema.json",
    "extends": [
        "local>basher83/renovate-config",
        "local>basher83/renovate-config//presets/python-mcp.json",
        "local>basher83/renovate-config//presets/github-actions-security.json",
        "local>basher83/renovate-config//presets/docker.json"
    ],
    "labels": [
        "dependencies",
        "renovate"
    ],
    "assignees": [
        "basher83"
    ],
    "commitMessagePrefix": "chore(deps):",
    "packageRules": [
        {
            "description": "Keep Python pinned below 3.14 until MCP SDK v1.x officially supports it",
            "matchDepNames": [
                "python"
            ],
            "allowedVersions": "<3.14"
        },
        {
            "description": "Update the Python pins in mise.toml and .python-version in one PR (scripts/validate.sh fails when they differ)",
            "matchManagers": [
                "mise",
                "pyenv"
            ],
            "matchDepNames": [
                "python"
            ],
            "groupName": "python version pins"
        },
        {
            "description": "Update the uv pins in mise.toml, the setup-uv steps, and the uv-pre-commit hook in one PR (scripts/validate.sh fails when they differ)",
            "matchDepNames": [
                "uv",
                "astral-sh/uv",
                "astral-sh/uv-pre-commit"
            ],
            "groupName": "uv version pins"
        },
        {
            "description": "Require approval for major Zammad API updates",
            "matchPackageNames": [
                "zammad-py"
            ],
            "matchUpdateTypes": [
                "major"
            ],
            "dependencyDashboardApproval": true
        }
    ]
}

presets/github-actions-security.json.content:
{
  "$schema": "https://docs.renovatebot.com/renovate-schema.json",
  "description": "GitHub Actions security preset - groups all updates, auto-merges low-risk changes into main, requires dashboard approval for security-sensitive updates",
  "packageRules": [
    {
      "description": "Pin GitHub Actions (uses:) to commit SHA digests for security",
      "matchManagers": [
        "github-actions"
      ],
      "matchDepTypes": [
        "action"
      ],
      "pinDigests": true
    },
    {
      "description": "Group all GitHub Actions updates together",
      "matchManagers": [
        "github-actions"
      ],
      "groupName": "GitHub Actions",
      "groupSlug": "github-actions"
    },
    {
      "description": "Auto-merge ALL GitHub Actions digest updates into main (no approval)",
      "matchManagers": [
        "github-actions"
      ],
      "matchUpdateTypes": [
        "digest"
      ],
      "automerge": true
    },
    {
      "description": "Auto-merge non-sensitive GitHub Actions patch, minor, and major updates into main (no approval)",
      "matchManagers": [
        "github-actions"
      ],
      "matchUpdateTypes": [
        "patch",
        "minor",
        "major"
      ],
      "matchPackageNames": [
        "!/^actions\\/checkout/",
        "!/^actions\\/upload-artifact/",
        "!/^actions\\/download-artifact/",
        "!/^aws-actions\\//",
        "!/^google-github-actions\\//",
        "!/^azure\\//",
        "!/^docker\\//"
      ],
      "automerge": true
    },
    {
      "description": "Require approval for security-sensitive GitHub Actions minor and major updates",
      "matchManagers": [
        "github-actions"
      ],
      "matchUpdateTypes": [
        "major",
        "minor"
      ],
      "dependencyDashboardApproval": true,
      "matchPackageNames": [
        "/^actions\\/checkout/",
        "/^actions\\/upload-artifact/",
        "/^actions\\/download-artifact/",
        "/^aws-actions\\//",
        "/^google-github-actions\\//",
        "/^azure\\//",
        "/^docker\\//"
      ]
    },
    {
      "description": "Label GitHub Actions PRs",
      "matchManagers": [
        "github-actions"
      ],
      "addLabels": [
        "github-actions",
        "security"
      ]
    }
  ]
}
